# ==================== FRAME HEX ====================
JOIN_FRAME_HEX = ""

ONLINE_ROOM_HEX = ""

# ==================== BUILD ACCOUNTS ====================
ACCOUNTS = []

for token in NEW_TOKENS:
    if not token or token.startswith("#"):
        continue
    fake_uid = generate_fake_uid()
    ACCOUNTS.append({
        "uid": fake_uid,
        "auth_token": token,
        "join_frame_hex": JOIN_FRAME_HEX,
        "online_room_frame_hex": ONLINE_ROOM_HEX
    })

